test('isolates credentials and handles protocol forms and redirects', async () => {
  const requests = [];
  const fetch = async (url, init) => {
    requests.push({ url: String(url), init });
    if (String(url).endsWith('/oauth/authorize')) return new Response(null, {status:302,headers:{Location:'https://storage.invalid/file'}});
    if (String(url).endsWith('/oauth/token')) return new Response('provider unavailable', {status:503});
    return new Response('{}');
  };
  const client = new SellApp({apiKey:'key',customerSession:'session',baseUrl:'https://mock.invalid/api',fetch});
  await client.get('/v2/orders');
  assert.equal(requests[0].init.headers.Authorization,'Bearer key');
  assert.equal(requests[0].init.headers['X-STORE'],undefined);
  await client.get('/v2/customer-portal/me');
  assert.equal(requests[1].init.headers.Authorization,'Bearer session');
  const redirect = await client.get('/oauth/authorize');
  assert.equal(redirect.status,302);
  assert.equal(redirect.headers.get('Location'),'https://storage.invalid/file');
  assert.equal(requests[2].url,'https://mock.invalid/oauth/authorize');
  assert.equal(requests[2].init.headers.Authorization,undefined);
  assert.equal(requests[2].init.redirect,'manual');
  await assert.rejects(client.post('/oauth/token',{grant_type:'refresh_token',refresh_token:'secret + value'}), error => error.status===503 && error.rawBody==='provider unavailable');
  assert.equal(requests.length,4);
  assert.equal(requests[3].init.headers['Content-Type'],'application/x-www-form-urlencoded');
  assert.equal(new URLSearchParams(requests[3].init.body).get('refresh_token'),'secret + value');
  const oauth = new SellApp({accessToken:'oauth',store:'store',fetch});
  await oauth.get('/v2/orders');
  assert.equal(requests[4].init.headers.Authorization,'Bearer oauth');
  assert.equal(requests[4].init.headers['X-STORE'],'store');
  await assert.rejects(new SellApp({accessToken:'oauth',fetch}).get('/v2/orders'));
});

