test('cancellation interrupts Retry-After without another request', async () => {
  const controller = new AbortController();
  let calls = 0;
  const client = new SellApp({apiKey:'key', store:'store', maxRetries:3, fetch: async () => {
    calls++; setTimeout(() => controller.abort(), 5);
    return new Response('busy', {status:429, headers:{'Retry-After':'999999'}});
  }});
  await assert.rejects(client.get('/items', {signal:controller.signal}), /cancelled/);
  assert.equal(calls, 1);
});

